const observedPrograms = new WeakMap<EsTreeNodeOfType<"Program">, EsTreeNodeOfType<"Program">>();
const observeProgram = (program: EsTreeNodeOfType<"Program">): EsTreeNodeOfType<"Program"> => {
  const existing = observedPrograms.get(program);
  if (existing) return existing;
  const observed = new Proxy(program, {
    get(target, property, receiver) {
      if (property !== "body") return Reflect.get(target, property, receiver);
      return new Proxy(target.body, {
        get(statements, statementProperty, statementReceiver) {
          if (statementProperty !== Symbol.iterator)
            return Reflect.get(statements, statementProperty, statementReceiver);
          return () => {
            const iterator = Array.prototype[Symbol.iterator].call(statements);
            return {
              next: () => {
                const result = iterator.next();
                if (!result.done) counters.exportStatements++;
                return result;
              },
            };
          };
        },
      });
    },
  });
  observedPrograms.set(program, observed);
  return observed;
};
