let directory = "";
beforeEach(() => {
  directory = fs.mkdtempSync(path.join(os.tmpdir(), "rd-deferred-work-"));
  fs.mkdirSync(path.join(directory, "src"));
  fs.writeFileSync(
    path.join(directory, "package.json"),
    '{"private":true,"dependencies":{"react":"19.0.0","react-dom":"19.0.0"}}',
  );
});
afterEach(() => {
  fs.rmSync(directory, { recursive: true, force: true });
  resetFilesystemCaches();
});
it.each(cases)("bounds real analysis work for $name", (entry) => {
  const measured = [];
  const exportMeasurements = [];
  const someCallbackMeasurements = [];
  for (const source of entry.sources) {
    const filename = path.join(directory, "src/preview.tsx");
    fs.writeFileSync(filename, source);
    resetFilesystemCaches();
    const parsed = parseFixture(source, { filename });
    expect(parsed.errors).toEqual([]);
    counters.visits = 0;
    counters.someCallbacks = 0;
    counters.exportStatements = 0;
    counters.exportIndexBuilds = 0;
    counters.genericExportCalls = 0;
    const descriptor = Object.getOwnPropertyDescriptor(Array.prototype, "some");
    if (!descriptor) throw new Error("Missing Array.some descriptor");
    const observedSome = new Proxy(Array.prototype.some, {
      apply: (target, receiver, argumentsList) =>
        Reflect.apply(target, receiver, [
          (...callbackArguments: unknown[]) => {
            counters.someCallbacks++;
            return Reflect.apply(argumentsList[0], argumentsList[1], callbackArguments);
          },
          argumentsList[1],
        ]),
    });
    let result;
    try {
      Object.defineProperty(Array.prototype, "some", { ...descriptor, value: observedSome });
      result = runRuleOnParsedFixture(iframeMissingSandbox, source, parsed, {
        filename,
        settings: { "react-doctor": { rootDirectory: directory } },
      });
    } finally {
      Object.defineProperty(Array.prototype, "some", descriptor);
    }
    expect(Object.getOwnPropertyDescriptor(Array.prototype, "some")).toEqual(descriptor);
    someCallbackMeasurements.push(counters.someCallbacks);
    expect(result.parseErrors).toEqual([]);
    expect(result.diagnostics).toHaveLength(entry.expectedDiagnosticCount);
    expect(counters.visits).toBeGreaterThan(0);
    if (entry.name === "shared-accepted-export") {
      exportMeasurements.push({
        exportIndexBuilds: counters.exportIndexBuilds,
        genericExportCalls: counters.genericExportCalls,
      });
    }
    measured.push(counters[entry.metric]);
  }
  const [small, large] = measured;
  expect(small).toBeGreaterThan(0);
  expect(large).toBeLessThanOrEqual(small * DEFERRED_IFRAME_MAX_WORK_GROWTH_RATIO);
  if (entry.name === "same-class-transparent-carriers") {
    const [smallCallbacks, largeCallbacks] = someCallbackMeasurements;
    expect(smallCallbacks).toBeGreaterThan(0);
    expect(largeCallbacks).toBeLessThanOrEqual(
      smallCallbacks * DEFERRED_IFRAME_MAX_WORK_GROWTH_RATIO,
    );
  }
  for (const measurement of exportMeasurements) {
    expect(measurement.exportIndexBuilds).toBe(1);
    expect(measurement.genericExportCalls).toBe(0);
  }
});
